#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    int findPairs(vector<int>& nums, int k) {
        if (k < 0) return 0;
        unordered_map<int, int> numCount;
        int count = 0;

        for (int num : nums) numCount[num]++;
        for (auto& [num, freq] : numCount) {
            if ((k > 0 && numCount.count(num + k)) || (k == 0 && freq > 1)) count++;
        }

        return count;
    }
};
